    ['topic' => 'Students & independent registration', 'question' => 'Can I start as a student before my school adopts AcadSyntra?', 'answer' => 'Yes. Your personal account, independent classrooms and research do not depend on an institution buying access.', 'steps' => ['Open Create account and choose Student.', 'Verify your email when required, then complete your profile and interests. You may leave optional institutional affiliation unset.', 'Use your dashboard, independent classrooms and Research Studio. Institutional courses still require an approved membership or authorised invitation.', 'When your department becomes available, connect this account through My Academic Affiliations; do not register again.'], 'links' => [['label' => 'Create your account', 'route' => 'register'], ['label' => 'Continue personal setup', 'route' => 'onboarding.show']]],
    ['topic' => 'Students & independent registration', 'question' => 'Will joining my department move or expose my personal research?', 'answer' => 'Joining creates a reviewed academic membership. It preserves your account, research, documents and academic history. Personal research remains restricted to its explicit participants.', 'steps' => ['Sign in with your existing account.', 'Open My Academic Affiliations and request membership or accept an email-bound invitation.', 'Wait for role-specific approval. A matching email domain does not grant privileges.', 'Switch to the approved workspace when you need its academic tools; return to Personal workspace for independent work.'], 'links' => [['label' => 'My Academic Affiliations', 'route' => 'academic.organisations']]],
