    ['topic' => 'Departmental onboarding', 'question' => 'How do autosave, verification and approval work?', 'answer' => 'The four-step wizard saves your own progress. Submitting an application places it in the platform review workflow; saving a draft does not grant access or create a charge.', 'steps' => ['Complete each step and wait for Progress saved before leaving.', 'Return using the same account to resume your draft.', 'Review the application and submit it once your authority evidence and contacts are correct.', 'Check the status and any review note on the department onboarding page.', 'Once approved, use the department dashboard and My Academic Affiliations. If rejected, follow the review note or ask support for clarification.'], 'links' => [['label' => 'Resume department setup', 'route' => 'department.onboarding']]],
