    ['topic' => 'Institutional onboarding', 'question' => 'How are institution administrators verified?', 'answer' => 'An institution administrator appointment requires authorised review. A public email domain, matching profile field or self-declared affiliation never automatically grants administrative privileges.', 'steps' => ['Submit the institution request as an authorised representative.', 'Provide evidence and official contact information for verification.', 'Wait for the platform to approve the claim and administrator appointment.', 'Complete the remaining institution setup under the approved administrative scope.', 'Use invitations or reviewed memberships for other staff; do not share administrator accounts.'], 'links' => [['label' => 'Institution onboarding', 'route' => 'institution.onboarding.request']]],
