    ['topic' => 'Department affiliation', 'question' => 'Our department adopted first. What happens when our institution adopts six months later?', 'answer' => 'Your department can connect through a two-party affiliation agreement. The platform does not delete, recreate, duplicate, overwrite or reparent departmental academic data during affiliation.', 'steps' => ['The institution completes verification and becomes active.', 'Its approved administrator proposes affiliation with your existing department.', 'Your department administrator reviews the proposal, sharing permissions, feature inheritance and billing preference.', 'Accept or decline. Acceptance waits for Platform Admin verification of both approvals.', 'After verification, the existing department becomes institution-affiliated. Existing IDs, memberships, courses and research remain intact.'], 'links' => [['label' => 'Review affiliation requests', 'route' => 'academic.organisations']]],
    ['topic' => 'Department affiliation', 'question' => 'Can a department decline affiliation or remain independent later?', 'answer' => 'Yes. A department can decline the proposal or retain control under its agreed policy. Either organisation can end an active affiliation without deleting the department.', 'steps' => ['Review the proposal as the current department administrator.', 'Decline if the terms or claimed authority are unsuitable.', 'For an active agreement, use End affiliation; retain department.', 'The department returns to independent operation; agreement and audit history remain.', 'Review which sponsored features remain available. Department balances and personal purchases are preserved.'], 'links' => [['label' => 'Manage agreements', 'route' => 'academic.organisations']]],
