    ['topic' => 'Invitations & membership', 'question' => 'My invitation was rejected, expired or sent to another email. What should I do?', 'answer' => 'Invitation links are single-use, expire and are bound to the intended verified email. A link does not grant administrator privileges.', 'steps' => ['Sign in to the account with the exact recipient email and verify it.', 'If the link expired or was revoked, ask the administrator for a fresh invitation.', 'If the wrong address was used, ask the administrator to revoke that invitation and issue a corrected one.', 'For a rejected access request, review its note and provide the requested evidence through the review workflow.', 'Keep your original account; contact support before creating duplicates to work around a failed invitation.'], 'links' => [['label' => 'Manage academic affiliations', 'route' => 'academic.organisations']]],
    ['topic' => 'Invitations & membership', 'question' => 'What do pending, approved, rejected and revoked membership statuses mean?', 'answer' => 'Pending awaits review; approved grants only the reviewed role and scope; rejected records a declined request; revoked ends the grant. Graduation and transfer preserve membership history.', 'steps' => ['Check the organisation and role shown in My Academic Affiliations.', 'Use only an approved, unexpired membership to switch workspaces.', 'Request review from the appropriate administrator when a pending request needs attention.', 'After revocation or transfer, use your personal workspace and any other valid affiliations.', 'A profile department or email domain is academic identity, not an access grant.'], 'links' => [['label' => 'Check memberships', 'route' => 'academic.organisations']]],
    ['topic' => 'Plans & access', 'question' => 'Do I need a subscription, and what are the department and institution plans?', 'answer' => 'AcadSyntra currently uses the existing commercial-account, wallet and entitlement system; the retired recurring-subscription system is not restarted. Core and Sponsored adoption arrangements request the appropriate scope and commercial review.', 'steps' => ['Choose a department or institution arrangement in onboarding.', 'Approval may open a commercial setup request; it does not automatically charge you.', 'Use Paid Features to inspect what is free, personally purchased or sponsored.', 'Use the existing commercial-account request workflow for organisation-funded access.', 'Feature release controls and your approved academic scope still apply.'], 'links' => [['label' => 'Paid features and sponsorship', 'route' => 'commerce.features']]],
    ['topic' => 'Plans & access', 'question' => 'What happens to paid access when a department affiliates or a plan expires?', 'answer' => 'Affiliation does not move balances, cancel personal purchases or create duplicate recurring subscriptions. Sponsorship follows the approved billing preference and active commercial terms.', 'steps' => ['Review the proposed department-first or institution-first billing preference.', 'Only one eligible commercial account funds a reservation.', 'If sponsorship expires or pauses, another eligible agreed sponsor may apply; otherwise personal access and wallet rules apply.', 'Refunds use the original reservation account even if the user changes academic workspace.', 'Contact the organisation administrator if a sponsored feature becomes unavailable; your personal academic records remain.'], 'links' => [['label' => 'Check access', 'route' => 'commerce.features']]],
    ['topic' => 'Research Studio & academic workflows', 'question' => 'How do I start and write a research or final-year project?', 'answer' => 'Research Studio brings project planning, chapter writing, references, data analysis, supervision and review into one workspace. Availability depends on the enabled tools and your approved academic context.', 'steps' => ['Open Research Studio and choose New research project or Final-Year Project.', 'Complete the project setup and plan before drafting chapters.', 'Select a chapter in the writing workspace. Collapse chapter navigation or use focus mode to make room for writing.', 'Save changes and review the save status. Use chapter history to inspect earlier versions.', 'Use references, analysis and supervisor review for the corresponding tasks; check the built-in workspace guide when unsure.'], 'links' => [['label' => 'Open Research Studio', 'route' => 'research.index'], ['label' => 'Start research', 'route' => 'research.create'], ['label' => 'Start a final-year project', 'route' => 'research.create', 'params' => ['studio_mode' => 'final_year']]]],
