    ['topic' => 'Notifications & preferences', 'question' => 'How do I enable push notifications on desktop, Android, iPhone or iPad?', 'answer' => 'Push is optional and requires a supported browser, HTTPS, browser permission, a valid device subscription and configured delivery. Where the browser and OS support it, push can arrive when the site is closed.', 'steps' => ['Sign in and choose Enable Notifications when invited, or open Notification Preferences.', 'On iPhone/iPad, add AcadSyntra to the Home Screen and open it from that icon first.', 'Click Enable this browser; browser permission is requested only after your click.', 'Keep Push Notifications enabled and use Send test notification to check provider acceptance.', 'If permission is denied, change the browser/OS notification setting manually. AcadSyntra does not repeatedly trigger denied permission prompts.'], 'links' => [['label' => 'Notification preferences', 'route' => 'notifications.settings']]],
    ['topic' => 'Notifications & preferences', 'question' => 'Can I control reminders, quiet hours and individual devices?', 'answer' => 'Yes. Academic, organisational, research, onboarding and optional engagement notifications have separate controls. Optional engagement is off until you opt in.', 'steps' => ['Open Notification Preferences.', 'Choose email, push and in-app channels and the categories you want.', 'Set your time zone and quiet-hour start/end; queued email and push wait until quiet hours end.', 'Use Not Now to snooze the browser invitation for seven days, or remove a specific device from the device list.', 'Optional reminder emails provide an unsubscribe link. Account security messages retain their separate authentication workflow.'], 'links' => [['label' => 'Manage notification settings', 'route' => 'notifications.settings']]],
    ['topic' => 'Notifications & preferences', 'question' => 'How often are onboarding and inactivity reminders sent?', 'answer' => 'The default onboarding schedule starts after 12 hours, has a minimum 12-hour gap, stops when the relevant setup is complete and slows after repeated ignored reminders. Administrators can reduce volume or configure the limit.', 'steps' => ['Open the reminder to resume the specific personal, departmental or institutional setup stage.', 'Submitted applications waiting for review are not treated as an unfinished department draft.', 'Optional inactivity reminders require consent and useful unfinished work. The planned stages are 24h, 48h, 7 days, 14 days and a reduced-frequency follow-up.', 'Returning or finishing the work cancels relevant queued inactivity reminders.', 'Disable onboarding or engagement reminders whenever you prefer.'], 'links' => [['label' => 'Continue setup', 'route' => 'onboarding.show'], ['label' => 'Reminder preferences', 'route' => 'notifications.settings']]],
    ['topic' => 'Notifications & preferences', 'question' => 'A message says accepted, but I did not receive it. Why?', 'answer' => 'Provider acceptance is not proof of device display or inbox delivery. Confirmed delivery is shown only when a supported provider reports it.', 'steps' => ['Check browser permission, OS notification settings, HTTPS and whether the device is enrolled.', 'Check spam/junk folders and your email preference.', 'Ask an administrator to inspect Notification Analytics for configured SMTP, VAPID, workers, retry status or expired subscriptions.', 'Log/array email transports are local simulations and cannot deliver to an inbox.', 'Contact support without sending passwords, subscription endpoints, encryption keys or confidential academic records.'], 'links' => [['label' => 'Notification settings', 'route' => 'notifications.settings'], ['label' => 'Contact support', 'route' => 'public.contact']]],
